UPDATE public.blocks SET settings = $rexerblk${"id":"b_y6542e5l","blockType":"mintv2_process","name":"Process","contentVi":{"desktop":{"eyebrow":"The Making","title":"From Brush to Strike","steps":[{"key":"s1","no":"01","title":"The Painting","body":"Tom Thomson paints The Jack Pine at Algonquin Park, capturing a windswept tree above an Ontario lake (1916–17)."},{"key":"s2","no":"02","title":"Engraving Sketch","body":"RCM master engravers translate the brushwork into millimetric relief — every needle, crag, and ripple plotted by hand."},{"key":"s3","no":"03","title":"Die Cutting","body":"Reverse and obverse dies are CNC-cut to the engraver's spec, then hand-finished for proof-level polish and frost zones."},{"key":"s4","no":"04","title":"The Strike","body":"1006.1 g of .99999 fine gold blanks are struck under specialised dies designed for kilo-scale coins. Multiple strikes ensure relief depth."},{"key":"s5","no":"05","title":"Presentation","body":"Each coin is encapsulated and presented in a Royal Canadian Mint–branded wooden case with black beauty box and serialised certificate."}]}},"contentEn":{"desktop":{"eyebrow":"The Making","title":"From Brush to Strike","steps":[{"key":"s1","no":"01","title":"The Painting","body":"Tom Thomson paints The Jack Pine at Algonquin Park, capturing a windswept tree above an Ontario lake (1916–17)."},{"key":"s2","no":"02","title":"Engraving Sketch","body":"RCM master engravers translate the brushwork into millimetric relief — every needle, crag, and ripple plotted by hand."},{"key":"s3","no":"03","title":"Die Cutting","body":"Reverse and obverse dies are CNC-cut to the engraver's spec, then hand-finished for proof-level polish and frost zones."},{"key":"s4","no":"04","title":"The Strike","body":"1006.1 g of .99999 fine gold blanks are struck under specialised dies designed for kilo-scale coins. Multiple strikes ensure relief depth."},{"key":"s5","no":"05","title":"Presentation","body":"Each coin is encapsulated and presented in a Royal Canadian Mint–branded wooden case with black beauty box and serialised certificate."}]}},"isVisible":true}$rexerblk$::jsonb
